<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch,computed} from 'vue';
import Map from 'ol/Map';import View from 'ol/View';import Feature from 'ol/Feature';
import Point from 'ol/geom/Point';import LineString from 'ol/geom/LineString';
import VectorSource from 'ol/source/Vector';import Cluster from 'ol/source/Cluster';
import VectorLayer from 'ol/layer/Vector';import Heatmap from 'ol/layer/Heatmap';
import {Style,Circle,Fill,Stroke,Text} from 'ol/style';
import {fromLonLat} from 'ol/proj';import DragBox from 'ol/interaction/DragBox';
import {defaults as interactions} from 'ol/interaction/defaults';
import type {Device} from '../domain';
import type {components} from '../api/schema';
type S=components['schemas'];
import {apiMode} from '../api/client';
const props=defineProps<{devices:Device[];selected:string[];trajectory?:string[];distribution?:boolean;points?:S['TrajectoryPoint'][];heatCells?:S['HeatCell'][]}>();
const emit=defineEmits<{select:[ids:string[]];detail:[id:string];reset:[];area:[geometry:S['GeoPolygon']];heat:[enabled:boolean]}>();
const host=ref<HTMLElement>(),tool=ref('single'),heat=ref(false),layer=ref('道路'),tip=ref(''),zoom=ref(11);let map:Map|undefined,observer:ResizeObserver|undefined,box:DragBox|undefined;
const source=new VectorSource(),trajectorySource=new VectorSource(),heatSource=new VectorSource(),clusterSource=new Cluster({distance:120,source});
const clusterItems=ref<{center:number[];count:number}[]>([]);
clusterSource.on('change',()=>{clusterItems.value=clusterSource.getFeatures().filter(f=>(f.get('features') as Feature[]).length>1).map(f=>({center:(f.getGeometry() as Point).getCoordinates(),count:(f.get('features') as Feature[]).length}));});
function expandCluster(center:number[]){map?.getView().animate({center,zoom:13,duration:200});}
const markers=new VectorLayer({source,style:feature=>{const d=props.devices.find(d=>d.id===feature.getId());return new Style({image:new Circle({radius:props.selected.includes(String(feature.getId()))?12:9,fill:new Fill({color:props.selected.includes(String(feature.getId()))?'#e88b34':d?.status==='离线'?'#7c8a9c':'#1769aa'}),stroke:new Stroke({color:'#fff',width:2})}),text:new Text({text:String((props.devices.findIndex(d=>d.id===feature.getId())+1)||''),fill:new Fill({color:'#fff'}),font:'11px sans-serif'})});}});
const clusters=new VectorLayer({source:clusterSource,style:f=>new Style({image:new Circle({radius:18,fill:new Fill({color:'#438870'}),stroke:new Stroke({color:'#fff',width:2})}),text:new Text({text:String((f.get('features') as Feature[]).length),fill:new Fill({color:'#fff'})})})});
const heatLayer=new Heatmap({source:apiMode==='mock'?source:heatSource,blur:22,radius:26,weight:f=>Number(f.get('weight'))||0,visible:false});
const path=new VectorLayer({source:trajectorySource,style:new Style({stroke:new Stroke({color:'#e88b34',width:4,lineDash:[7,3]}),image:new Circle({radius:6,fill:new Fill({color:'#e88b34'}),stroke:new Stroke({color:'#fff',width:1})})})});
const background=new VectorLayer({source:new VectorSource({features:Array.from({length:8},(_,i)=>new Feature({geometry:new LineString([fromLonLat([116.2+i*.07,39.65]),fromLonLat([116.2+i*.07,40.15])])})).concat(Array.from({length:8},(_,i)=>new Feature({geometry:new LineString([fromLonLat([116.2,39.65+i*.07]),fromLonLat([116.7,39.65+i*.07])])})))}),style:new Style({stroke:new Stroke({color:'#d7e2e9',width:4})})});
const coordinate=(d:Device)=>fromLonLat(apiMode==='http'&&d.longitude!=null&&d.latitude!=null?[d.longitude,d.latitude]:[116.2+d.x/200,39.65+d.y/200]);
function refresh(){source.clear();source.addFeatures(props.devices.filter(d=>apiMode==='mock'||d.longitude!=null&&d.latitude!=null).map(d=>{const f=new Feature({geometry:new Point(coordinate(d)),name:d.name,weight:Math.min(1,d.count/3500)});f.setId(d.id);return f;}));trajectorySource.clear();const points=(props.trajectory||[]).map(id=>props.devices.find(d=>d.id===id)).filter((d):d is Device=>!!d&&(apiMode==='mock'||d.longitude!=null&&d.latitude!=null)).map(coordinate);if(points.length>1)trajectorySource.addFeature(new Feature({geometry:new LineString(points)}));if(apiMode==='http'){const groups=new globalThis.Map<string,number[][]>();for(const point of props.points||[]){const key=point.target.targetId+':'+point.target.targetType,coordinates=fromLonLat(point.location.coordinates);if(!groups.has(key))groups.set(key,[]);groups.get(key)!.push(coordinates);trajectorySource.addFeature(new Feature({geometry:new Point(coordinates),name:point.captureTime}));}for(const coordinates of groups.values())if(coordinates.length>1)trajectorySource.addFeature(new Feature({geometry:new LineString(coordinates)}));heatSource.clear();const max=Math.max(1,...(props.heatCells||[]).map(c=>c.value));heatSource.addFeatures((props.heatCells||[]).map(c=>new Feature({geometry:new Point(fromLonLat(c.center.coordinates)),weight:c.value/max,name:String(c.value)+' '+c.unit})));const fit=source.getFeatures().length?source:trajectorySource;const extent=fit.getExtent();if(fit.getFeatures().length&&extent)map?.getView().fit(extent,{padding:[50,50,50,50],maxZoom:13,duration:0});}markers.changed();}
function reset(){tool.value='single';heat.value=false;layer.value='道路';emit('select',[]);emit('reset');const extent=source.getExtent();if(apiMode==='http'&&source.getFeatures().length&&extent)map?.getView().fit(extent,{padding:[50,50,50,50],maxZoom:13,duration:0});else{map?.getView().setCenter(fromLonLat(apiMode==='mock'?[116.45,39.9]:[0,0]));map?.getView().setZoom(apiMode==='mock'?11:2);}}
function settings(){box?.setActive(tool.value==='box');heatLayer.setVisible(heat.value);markers.setVisible(!heat.value&&(!props.distribution||zoom.value>=12));clusters.setVisible(!heat.value&&!!props.distribution&&zoom.value<12);}
onMounted(()=>{map=new Map({target:host.value,layers:apiMode==='mock'?[background,heatLayer,path,markers,clusters]:[heatLayer,path,markers,clusters],view:new View({center:fromLonLat([116.45,39.9]),zoom:11,minZoom:2,maxZoom:17}),interactions:interactions({dragPan:false})});box=new DragBox({condition:()=>tool.value==='box'});map.addInteraction(box);box.on('boxend',()=>{const extent=box?.getGeometry().getExtent();if(extent){const ids:string[]=[];source.forEachFeatureIntersectingExtent(extent,f=>{ids.push(String(f.getId()));});emit('select',ids);const geometry=box!.getGeometry().clone().transform('EPSG:3857','EPSG:4326');emit('area',{type:'Polygon',coordinates:geometry.getCoordinates()});}});map.on('singleclick',event=>{if(tool.value!=='single')return;const hits=map?.getFeaturesAtPixel(event.pixel)||[];const cluster=hits.find(f=>f.get('features'));if(cluster){map?.getView().animate({center:cluster.getGeometry() instanceof Point?(cluster.getGeometry() as Point).getCoordinates():event.coordinate,zoom:13,duration:200});return;}const id=hits.map(f=>f.getId()).find(Boolean);if(id)emit('select',[String(id)]);});map.on('pointermove',event=>{const f=map?.getFeaturesAtPixel(event.pixel)[0];tip.value=f?.get('name')||'';});map.getView().on('change:resolution',()=>{zoom.value=map?.getView().getZoom()||11;settings();});observer=new ResizeObserver(()=>map?.updateSize());if(host.value)observer.observe(host.value);refresh();settings();});watch(()=>[props.devices,props.trajectory,props.points,props.heatCells],refresh,{deep:true});watch(()=>props.selected,()=>markers.changed(),{deep:true});watch([tool,heat],settings);watch(heat,value=>emit('heat',value));onBeforeUnmount(()=>{observer?.disconnect();map?.setTarget(undefined);map?.dispose();});
defineExpose({reset});
const online=computed(()=>props.devices.filter(d=>d.status==='在线').length);
</script>
<template><section class="card map-card"><div class="section-head"><h3>设备空间视图</h3><el-button :type="tool==='box'?'primary':'default'" @click="tool='box'">框选</el-button><el-button :type="tool==='single'?'primary':'default'" @click="tool='single'">{{distribution?'手动选择':'单选'}}</el-button><el-button @click="reset">重置地图</el-button><el-button :aria-pressed="heat" :type="heat?'primary':'default'" @click="heat=!heat">热力图</el-button><el-button v-if="apiMode==='mock'" @click="layer=layer==='道路'?'地形':'道路'">图层：{{layer}}</el-button></div><div ref="host" class="map-canvas" :class="{terrain:layer==='地形'&&apiMode==='mock'}" role="img" :aria-label="apiMode==='mock'?'演示设备地图':'设备点位图，WGS84 坐标，无授权底图'"/><div class="map-caption"><span>{{tip||'蓝色：在线设备 · 灰色：离线设备 · 橙色：选择 / 轨迹'}}</span><span>在线 {{online}} / {{devices.length}} · {{distribution?(zoom<12?'聚合视图':'点位视图'):'轨迹视图'}} · {{tool==='box'?'拖动鼠标框选':'单击点位'}} · {{apiMode==='mock'?'Mock 演示底图':'WGS84 点位，底图待授权'}}</span></div><details class="map-keyboard"><summary>设备选择列表（支持键盘）</summary><div v-if="distribution&&zoom<12&&!heat" class="actions"><el-button v-for="(cluster,i) in clusterItems" :key="i" @click="expandCluster(cluster.center)">聚合 {{cluster.count}} 台设备 · 放大</el-button></div><el-checkbox-group :model-value="selected" @update:model-value="emit('select',$event.map(String))"><el-checkbox v-for="d in devices" :key="d.id" :value="d.id">{{d.name}} · {{d.site}} · {{d.status}}</el-checkbox></el-checkbox-group></details></section></template>

